"""Export a sandwich certificate as a Lean file checked by the verified Lean checker.

The generated file contains only data plus `decide +kernel` calls of the executable
checkers `MACRN.checkUpper` / `MACRN.checkLower`, whose soundness theorems are proved
in `RequestProject/AION/Checker.lean`.  The final theorem states the probability
bounds about the hitting probability of the (infinite-state) jump chain.
"""
from __future__ import annotations

from fractions import Fraction
from typing import Dict


def _dy(q: Fraction):
    """Exact (mantissa, exponent) with q = m / 2^e (q must be dyadic)."""
    den = q.denominator
    e = den.bit_length() - 1
    if den != 1 << e:
        raise ValueError(f"non-dyadic table entry {q}")
    return q.numerator, e


def _q_lean(q: Fraction) -> str:
    if q.denominator == 1:
        return f"({q.numerator} : ℚ)"
    return f"(({q.numerator} : ℚ) / {q.denominator})"


def _vec(xs):
    return "![" + ", ".join(xs) + "]"


def _table(name, tab: Dict[str, str], box):
    import itertools
    entries = []
    for x in itertools.product(*[range(b) for b in box]):
        q = Fraction(tab[",".join(map(str, x))])
        m, e = _dy(q)
        entries.append(f"({m}, {e})")
    return f"def {name} : Array (ℤ × ℕ) := #[{', '.join(entries)}]\n"


def emit(cert, ns: str, path: str):
    model = cert["model"]
    d = len(model["species"])
    rx = model["reactions"]
    n = len(rx)
    box_u = cert["upper"]["box"]
    box_l = cert["lower"]["box"]
    jB = cert["target"]["species"]
    lvl = cert["target"]["level"]
    zero = cert["taboo_zero"]
    x0 = cert["x0"]

    def idx_expr(box):
        strides = []
        s = 1
        for b in reversed(box):
            strides.append(s)
            s *= b
        strides = list(reversed(strides))
        return " + ".join(f"x {i} * {strides[i]}" for i in range(d))

    L = []
    L.append("import RequestProject.AION.Checker\n")
    L.append("/-! Auto-generated by `python/aion/emit_lean.py`. Do not edit by hand.\n")
    L.append(f"Species: {model['species']}.  Reactions:\n")
    for R in rx:
        L.append(f"* {R.get('name','')}: {R['inp']} -> {R['out']}, k = {R['k']}\n")
    L.append(f"Target: species {jB} reaches {lvl}.  Taboo: extinction of species "
             f"{[i for i in range(d) if zero[i]]}.  Start: {x0}. -/\n\n")
    L.append("namespace AION.Examples." + ns + "\n\nopen AION AION.MACRN\n\n")
    L.append(f"def net : MACRN {d} {n} where\n")
    L.append("  inp := " + _vec([_vec([str(a) for a in R["inp"]]) for R in rx]) + "\n")
    L.append("  out := " + _vec([_vec([str(a) for a in R["out"]]) for R in rx]) + "\n")
    L.append("  k := " + _vec([_q_lean(Fraction(R["k"])) for R in rx]) + "\n")
    L.append("  k_nonneg := by intro r; fin_cases r <;> norm_num\n\n")
    L.append("def zero : Fin %d → Bool := %s\n\n" % (d, _vec(["true" if z else "false" for z in zero])))
    L.append(_table("Ttab", cert["upper"]["table"], box_u))
    L.append(_table("Ftab", cert["lower"]["F"], box_l))
    L.append(_table("Vtab", cert["lower"]["V"], box_l))
    L.append("\n@[inline] def look (a : Array (ℤ × ℕ)) (i : ℕ) : ℚ :=\n"
             "  let p := a.getD i (0, 0); (p.1 : ℚ) / (2 : ℚ) ^ p.2\n\n")
    L.append("def ucert : UpperCert %d where\n" % d)
    L.append(f"  jB := {jB}\n  lvl := {lvl}\n  zero := zero\n")
    L.append("  box := " + _vec([str(b) for b in box_u]) + "\n")
    L.append(f"  T := fun x => look Ttab ({idx_expr(box_u)})\n")
    L.append("  C := " + _q_lean(Fraction(cert["upper"]["C"])) + "\n")
    L.append("  ρ := " + _vec([_q_lean(Fraction(r)) for r in cert["upper"]["rho"]]) + "\n\n")
    L.append("def lcert : LowerCert %d where\n" % d)
    L.append(f"  jB := {jB}\n  lvl := {lvl}\n")
    L.append("  box := " + _vec([str(b) for b in box_l]) + "\n")
    L.append(f"  F := fun x => look Ftab ({idx_expr(box_l)})\n")
    L.append(f"  V := fun x => look Vtab ({idx_expr(box_l)})\n\n")
    L.append("def x0 : Fin %d → ℕ := %s\n\n" % (d, _vec([str(v) for v in x0])))
    Lc = Fraction(cert["claim"]["lower"])
    Uc = Fraction(cert["claim"]["upper"])
    L.append("theorem upper_ok : net.checkUpper ucert = true := by decide +kernel\n\n")
    L.append("theorem lower_ok : net.checkLower (tabooA zero) lcert = true := by decide +kernel\n\n")
    L.append(f"theorem upper_val : ucert.g x0 ≤ {_q_lean(Uc)} := by decide +kernel\n\n")
    L.append(f"theorem lower_val : {_q_lean(Lc)} ≤ lcert.f (tabooA zero) x0 := by decide +kernel\n\n")
    L.append("/-- **Certified sandwich** for the infinite-state network: the probability that\n"
             f"species {jB} reaches {lvl} before extinction of a taboo species, from `x0`. -/\n")
    L.append("theorem sandwich :\n"
             f"    (({Lc.numerator} : ℝ) / {Lc.denominator}) ≤\n"
             f"      net.toJump.hitProb {{y | tabooA zero y = true}} {{y | {lvl} ≤ y {jB}}} x0 ∧\n"
             f"    net.toJump.hitProb {{y | tabooA zero y = true}} {{y | {lvl} ≤ y {jB}}} x0 ≤\n"
             f"      (({Uc.numerator} : ℝ) / {Uc.denominator}) := by\n")
    L.append("  have hU := net.checkUpper_sound upper_ok x0\n")
    L.append("  have hL := net.checkLower_sound lower_ok x0\n")
    L.append("  have hu : ((ucert.g x0 : ℚ) : ℝ) ≤ " +
             f"(({Uc.numerator} : ℚ) / {Uc.denominator} : ℚ) := by exact_mod_cast upper_val\n")
    L.append("  have hl : " + f"(({Lc.numerator} : ℚ) / {Lc.denominator} : ℚ) ≤ " +
             "((lcert.f (tabooA zero) x0 : ℚ) : ℝ) := by exact_mod_cast lower_val\n")
    L.append("  push_cast at hu hl\n")
    L.append("  exact ⟨le_trans hl hL, le_trans hU hu⟩\n\n")
    L.append("end AION.Examples." + ns + "\n")
    with open(path, "w") as f:
        f.write("".join(L))
